    def record(self, ticket: Ticket, success: bool) -> Optional[tuple[BreakerState, BreakerState]]:
        """回传一次请求结果；返回发生的迁移 (旧状态, 新状态)，无迁移为 None。"""
        with self._lock:
            # 过期票据直接丢弃，防止在途请求的晚到回调污染新一轮状态
            if ticket.generation != self._generation or not ticket.allowed:
                return None

            self.total_calls += 1
            if not success:
                self.total_failures += 1

            if self._state is BreakerState.CLOSED:
                self._window.append((self._clock(), success))
                self._evict_window_locked()
                if success:
                    self._consecutive_fail = 0
                else:
                    self._consecutive_fail += 1
                if self._should_trip_locked():
                    return self._transition_locked(BreakerState.OPEN)
                return None

            if self._state is BreakerState.HALF_OPEN:
                self._probe_inflight = max(0, self._probe_inflight - 1)
                if success:
                    self._probe_successes += 1
                    if self._probe_successes >= self.success_threshold:
                        return self._transition_locked(BreakerState.CLOSED)
                else:
                    return self._transition_locked(BreakerState.OPEN)
                return None

            return None

    def _should_trip_locked(self) -> bool:
        if self._consecutive_fail >= self.consecutive_failures:
            return True
        total = len(self._window)
        if total < self.min_request_volume:
            return False
        failures = sum(1 for _, ok in self._window if not ok)
        return failures / total >= self.error_rate_threshold

    def _peek_state_locked(self) -> BreakerState:
        """锁内读取状态；冷却窗口到期则惰性迁移到 HALF_OPEN。"""
        if self._state is BreakerState.OPEN:
            if self._clock() - self._opened_at >= self.cooldown_seconds:
                self._apply_locked(BreakerState.HALF_OPEN)
        return self._state

    def _transition_locked(self, new_state: BreakerState) -> tuple[BreakerState, BreakerState]:
        old_state = self._state
        self._apply_locked(new_state)
        if new_state is BreakerState.OPEN:
            self.trip_count += 1
        if self._on_transition is not None:
            node_id = self.node_id
            listener = self._on_transition
            # 在锁外派发，避免与上层 mesh 锁形成环路
            timer = threading.Timer(0, lambda: listener(node_id, old_state, new_state))
            timer.daemon = True
            timer.start()
        return old_state, new_state

    def _apply_locked(self, new_state: BreakerState) -> None:
        self._state = new_state
        self._generation += 1
        if new_state is BreakerState.OPEN:
            self._opened_at = self._clock()
            self._probe_inflight = 0
            self._probe_successes = 0
        elif new_state is BreakerState.HALF_OPEN:
            self._probe_inflight = 0
            self._probe_successes = 0
        elif new_state is BreakerState.CLOSED:
            self._window.clear()
            self._consecutive_fail = 0
            self._probe_inflight = 0
            self._probe_successes = 0

    def _evict_window_locked(self) -> None:
        cutoff = self._clock() - self.window_seconds
        while self._window and self._window[0][0] < cutoff:
            self._window.popleft()

    def snapshot(self) -> dict:
        with self._lock:
            state = self._peek_state_locked()
            self._evict_window_locked()
            window = list(self._window)
            total = len(window)
            failures = sum(1 for _, ok in window if not ok)
            error_rate = (failures / total) if total else 0.0
            retry_after = 0.0
            if state is BreakerState.OPEN:
                retry_after = max(0.0, self.cooldown_seconds - (self._clock() - self._opened_at))
            return {
                "state": state.value,
                "state_label": _STATE_LABELS[state],
                "generation": self._generation,
                "error_rate": round(error_rate, 3),
                "window_total": total,
                "consecutive_failures": self._consecutive_fail,
                "probe_inflight": self._probe_inflight,
                "probe_successes": self._probe_successes,
                "retry_after": round(retry_after, 2),
                "total_calls": self.total_calls,
                "total_failures": self.total_failures,
                "total_rejected": self.total_rejected,
                "trip_count": self.trip_count,
            }
