:root {
  --bg: #0d1117;
  --bg-2: #141b26;
  --panel: #161e2b;
  --border: #243044;
  --text: #dbe4f0;
  --muted: #8295ab;
  --ok: #2ecc71;
  --warn: #f1b944;
  --bad: #ff5d5d;
  --half: #48b8ff;
  --accent: #6c8cff;
  --mono: "Cascadia Mono", Consolas, "Courier New", monospace;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 14px;
  min-height: 100vh;
}

.topbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 18px; gap: 16px;
  background: linear-gradient(180deg, #15202e, #101722);
  border-bottom: 1px solid var(--border);
  flex-wrap: wrap;
}
.brand { display: flex; align-items: center; gap: 12px; }
.logo { font-size: 34px; color: var(--accent); text-shadow: 0 0 14px rgba(108,140,255,.6); }
.topbar h1 { font-size: 17px; margin: 0; letter-spacing: .5px; }
.subtitle { color: var(--muted); font-size: 12px; }

.metrics { display: flex; gap: 10px; flex-wrap: wrap; }
.metric {
  display: flex; align-items: baseline; gap: 5px;
  background: var(--panel); border: 1px solid var(--border);
  border-radius: 8px; padding: 6px 12px; min-width: 96px;
}
.metric-label { color: var(--muted); font-size: 11px; width: 100%; display: block; margin-bottom: 2px; }
.metric { flex-direction: column; }
.metric-value { font-size: 20px; font-weight: 700; font-family: var(--mono); }
.metric-unit { color: var(--muted); font-size: 11px; }
.metric.ok .metric-value { color: var(--ok); }
.metric.bad .metric-value { color: var(--bad); }
.metric.warn .metric-value { color: var(--warn); }

.controls {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
  padding: 10px 18px; background: var(--bg-2);
  border-bottom: 1px solid var(--border);
}
.btn {
  background: #1d2939; color: var(--text); border: 1px solid var(--border);
  border-radius: 8px; padding: 8px 14px; font-size: 13px; cursor: pointer;
  transition: transform .08s, background .15s, border-color .15s;
}
.btn:hover { background: #253349; border-color: #3a4d6d; }
.btn:active { transform: translateY(1px); }
.btn:disabled { opacity: .5; cursor: not-allowed; }
.btn-primary { background: linear-gradient(135deg, #4164e8, #6c8cff); border-color: #4164e8; font-weight: 600; }
.btn-primary:hover { background: linear-gradient(135deg, #4d6ff0, #7c99ff); }
.btn-warn { border-color: #6e5520; }
.btn-warn:hover { background: #33280f; }
.btn-ok { border-color: #1f5d39; }
.btn-ok:hover { background: #10301f; }
.btn-ghost { background: transparent; color: var(--muted); }
.rate-control { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 12px; margin-left: auto; }
#rate-value { color: var(--text); font-family: var(--mono); min-width: 64px; }
.demo-banner {
  color: var(--warn); font-weight: 600; font-size: 13px;
  animation: blink 1.2s ease-in-out infinite;
}
@keyframes blink { 50% { opacity: .45; } }

.layout {
  display: grid; grid-template-columns: minmax(0, 1fr) 330px;
  gap: 12px; padding: 12px 18px;
}
.panel {
  background: var(--panel); border: 1px solid var(--border);
  border-radius: 10px; overflow: hidden;
}
.panel-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 9px 14px; border-bottom: 1px solid var(--border);
  background: rgba(255,255,255,.02);
}
.panel-head h2 { margin: 0; font-size: 13px; font-weight: 600; color: #b7c6db; }
.legend { display: flex; gap: 14px; color: var(--muted); font-size: 12px; align-items: center; }
.dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 4px; }
.dot-closed { background: var(--ok); }
.dot-half { background: var(--half); }
.dot-open { background: var(--bad); }
.line-legend { display: inline-block; width: 22px; border-top: 3px solid var(--accent); vertical-align: middle; margin-right: 4px; }

.canvas-panel { min-height: 480px; display: flex; flex-direction: column; }
#topo { width: 100%; flex: 1; display: block; }

.nodes-panel { max-height: 540px; display: flex; flex-direction: column; }
.node-cards { overflow-y: auto; padding: 10px; display: flex; flex-direction: column; gap: 8px; }
.node-card {
  border: 1px solid var(--border); border-radius: 8px; padding: 9px 11px;
  background: #121a26; transition: border-color .25s, box-shadow .25s;
}
.node-card.state-OPEN { border-color: rgba(255,93,93,.7); box-shadow: 0 0 0 1px rgba(255,93,93,.25), 0 0 18px rgba(255,93,93,.18); }
.node-card.state-HALF_OPEN { border-color: rgba(72,184,255,.7); box-shadow: 0 0 0 1px rgba(72,184,255,.2), 0 0 18px rgba(72,184,255,.15); }
.node-card.state-CLOSED { border-color: rgba(46,204,113,.28); }
.nc-head { display: flex; justify-content: space-between; align-items: center; }
.nc-name { font-family: var(--mono); font-size: 13px; font-weight: 600; }
.nc-addr { color: var(--muted); font-size: 11px; font-family: var(--mono); }
.badge { font-size: 11px; padding: 2px 8px; border-radius: 10px; font-weight: 600; }
.badge-closed { background: rgba(46,204,113,.15); color: var(--ok); }
.badge-half_open { background: rgba(72,184,255,.15); color: var(--half); }
.badge-open { background: rgba(255,93,93,.16); color: var(--bad); }
.nc-row { display: flex; align-items: center; gap: 8px; margin-top: 6px; font-size: 11.5px; color: var(--muted); }
.health-bar { flex: 1; height: 6px; background: #0c121b; border-radius: 3px; overflow: hidden; }
.health-fill { height: 100%; border-radius: 3px; transition: width .4s, background-color .4s; }
.nc-stats { display: flex; gap: 12px; margin-top: 6px; font-size: 11px; color: #9db0c7; font-family: var(--mono); }
.nc-stats b { color: var(--text); }
.fault-tag { color: var(--warn); font-size: 11px; margin-top: 4px; }

.logs-panel { margin: 0 18px 18px; }
.autoscroll { color: var(--muted); font-size: 12px; user-select: none; }
.logs {
  height: 210px; overflow-y: auto; padding: 8px 14px;
  font-family: var(--mono); font-size: 12.5px; line-height: 1.7;
  background: #0b1018;
}
.log-line { white-space: pre-wrap; }
.log-time { color: #5c6f86; margin-right: 8px; }
.log-level { display: inline-block; min-width: 44px; font-weight: 700; margin-right: 8px; }
.log-INFO .log-level { color: var(--accent); }
.log-WARN .log-level { color: var(--warn); }
.log-ERROR .log-level { color: var(--bad); }
.log-INFO { color: #aebfd4; }
.log-WARN { color: #e5cf9e; }
.log-ERROR { color: #ff9d9d; }

@media (max-width: 980px) {
  .layout { grid-template-columns: 1fr; }
}
'@; [System.IO.File]::WriteAllText((Join-Path (Get-Location) $p), $c, (New-Object System.Text.UTF8Encoding($false))); echo css-ok"}

