  function drawGateway(g) {
    ctx.save();
    var grd = ctx.createLinearGradient(g.x - 38, g.y - 30, g.x + 38, g.y + 30);
    grd.addColorStop(0, "#3a4f8f");
    grd.addColorStop(1, "#6c8cff");
    ctx.fillStyle = grd;
    ctx.shadowColor = "rgba(108,140,255,.55)";
    ctx.shadowBlur = 20;
    roundRect(ctx, g.x - 40, g.y - 30, 80, 60, 10);
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.fillStyle = "#eef3ff";
    ctx.font = "bold 12px Segoe UI, sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("GATEWAY", g.x, g.y - 4);
    ctx.font = "10px Consolas, monospace";
    ctx.fillText("LB + 限流", g.x, g.y + 13);
    ctx.textAlign = "left";
    ctx.restore();
  }

  function drawNode(p, node) {
    var st = node.breaker_state;
    var color = stateColor[st];
    ctx.save();
    // 外圈：熔断告警脉冲
    if (st === "OPEN" || st === "HALF_OPEN") {
      var pulse = (performance.now() / 600) % 1;
      ctx.strokeStyle = stateColorSoft[st] + (0.6 * (1 - pulse)) + ")";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r + 5 + pulse * 10, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.fillStyle = "#141e2c";
    ctx.strokeStyle = color;
    ctx.lineWidth = 2.5;
    ctx.shadowColor = stateColorSoft[st] + "0.55)";
    ctx.shadowBlur = st === "CLOSED" ? 6 : 16;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.shadowBlur = 0;

    // 健康环
    ctx.strokeStyle = "rgba(255,255,255,.12)";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r - 5, 0, Math.PI * 2);
    ctx.stroke();
    ctx.strokeStyle = healthColor(node.health);
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r - 5, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * node.health);
    ctx.stroke();

    ctx.fillStyle = "#e6eefb";
    ctx.font = "bold 11px Consolas, monospace";
    ctx.textAlign = "center";
    ctx.fillText(node.node_id.split("-").map(function (w) { return w.slice(0, 4); }).join("-"), p.x, p.y + 3.5);
    ctx.textAlign = "left";
    ctx.fillStyle = "#8ea0bb";
    ctx.font = "10px Consolas, monospace";
    ctx.textAlign = "center";
    ctx.fillText(Math.round(node.ewma_latency_ms) + "ms", p.x, p.y + p.r + 15);
    ctx.textAlign = "left";
    ctx.restore();
  }

  function healthColor(h) {
    if (h > 0.66) return "#2ecc71";
    if (h > 0.33) return "#f1b944";
    return "#ff5d5d";
  }

  // ------------------------------------------------------------ 节点卡片
  function renderCards(state) {
    var nodes = state.mesh.nodes;
    var html = Object.keys(nodes).map(function (id) {
      var n = nodes[id];
      var b = n.breaker;
      var st = n.breaker_state;
      var hPct = Math.round(n.health * 100);
      var fault = n.inject_latency_ms > 0 || n.inject_loss > 0
        ? '<div class="fault-tag">🐢 故障注入: ' + (n.inject_latency_ms ? "+" + Math.round(n.inject_latency_ms) + "ms " : "") +
          (n.inject_loss ? Math.round(n.inject_loss * 100) + "% 错误" : "") + "</div>"
        : "";
      var extra = st === "OPEN"
        ? '<span style="color:var(--bad)">冷却剩余 ' + b.retry_after + 's</span>'
        : st === "HALF_OPEN"
          ? '<span style="color:var(--half)">试探成功 ' + b.probe_successes + '/3</span>'
          : '<span style="color:var(--muted)">窗口错误率 ' + Math.round(b.error_rate * 100) + '%</span>';
      return '<div class="node-card state-' + st + '">' +
        '<div class="nc-head"><span class="nc-name">' + id + '</span>' +
        '<span class="badge badge-' + st.toLowerCase() + '">' + b.state_label + "</span></div>" +
        '<div class="nc-addr">' + n.address + " · " + n.service + "-service</div>" +
        '<div class="nc-row"><span>健康</span><div class="health-bar"><div class="health-fill" style="width:' + hPct +
          "%;background:" + healthColor(n.health) + '"></div></div><span>' + hPct + "%</span></div>" +
        '<div class="nc-stats"><span>延迟 <b>' + Math.round(n.ewma_latency_ms) + "ms</b></span>" +
          '<span>在途 <b>' + n.in_flight + "/" + n.inflight_cap + "</b></span>" +
          '<span>权重 <b>' + n.effective_weight + "</b></span></div>" +
        '<div class="nc-stats"><span>失败 <b>' + b.total_failures + "</b></span>" +
          '<span>拦截 <b>' + b.total_rejected + "</b></span>" +
          '<span>熔断 <b>' + b.trip_count + "</b></span></div>" +
        '<div class="nc-row">' + extra + "</div>" + fault + "</div>";
    }).join("");
    nodeCards.innerHTML = html;
  }

  // ------------------------------------------------------------ 指标与日志
  function renderMetrics(state) {
    var m = state.mesh;
    document.getElementById("m-rps").textContent = m.rps;
    document.getElementById("m-rps-ok").textContent = m.rps_ok;
    document.getElementById("m-rps-fail").textContent = m.rps_fail;
    document.getElementById("m-inflight").textContent = m.inflight;
    document.getElementById("m-limited").textContent = m.counters.limited;
    document.getElementById("m-fastfail").textContent = m.counters.fast_fail;
    document.getElementById("m-uptime").textContent = m.uptime;
    document.getElementById("demo-banner").hidden = !state.traffic.running_demo;
    document.getElementById("btn-demo").disabled = state.traffic.running_demo;
  }

  function appendLogs(entries) {
    var frag = document.createDocumentFragment();
    entries.forEach(function (e) {
      var div = document.createElement("div");
      div.className = "log-line log-" + e.level;
      var t = document.createElement("span"); t.className = "log-time"; t.textContent = e.time;
      var lv = document.createElement("span"); lv.className = "log-level"; lv.textContent = e.level;
      var msg = document.createElement("span"); msg.textContent = e.message;
      div.appendChild(t); div.appendChild(lv); div.appendChild(msg);
      frag.appendChild(div);
    });
    logsEl.appendChild(frag);
    while (logsEl.childNodes.length > 300) logsEl.removeChild(logsEl.firstChild);
    if (document.getElementById("autoscroll").checked) logsEl.scrollTop = logsEl.scrollHeight;
  }

  // ------------------------------------------------------------ 主循环
  function tick() {
    getState(lastSeq).then(function (state) {
      lastState = state;
      if (state.logs && state.logs.length) {
        lastSeq = state.logs[state.logs.length - 1].seq;
        appendLogs(state.logs);
      }
      renderMetrics(state);
      renderCards(state);
      if (!layoutCache || needsRelayout(state)) layoutCache = buildLayout(state);
      draw(layoutCache, state);
    }).catch(function () { /* 轮询失败静默重试 */ });
  }

  function needsRelayout(state) {
    var ids = Object.keys(state.mesh.nodes).join(",");
    return ids !== (layoutCache._ids || (layoutCache._ids = ids)) && false;
  }

  // 尺寸变化时重建布局
  window.addEventListener("resize", function () { layoutCache = null; });
  setInterval(tick, 500);
  requestAnimationFrame(function anim() {
    if (lastState) {
      if (!layoutCache) layoutCache = buildLayout(lastState);
      draw(layoutCache, lastState);
    }
    requestAnimationFrame(anim);
  });

  // ------------------------------------------------------------ 控件
  document.getElementById("btn-demo").addEventListener("click", function () { post("/api/demo"); });
  document.getElementById("btn-burst").addEventListener("click", function () { post("/api/burst", { count: 120 }); });
  document.getElementById("btn-fault").addEventListener("click", function () {
    post("/api/inject", { node: "payment-2", latency_ms: 700, loss: 0.4 });
  });
  document.getElementById("btn-clear").addEventListener("click", function () {
    post("/api/clear", { node: "payment-2" });
  });
  document.getElementById("btn-reset").addEventListener("click", function () {
