      div.appendChild(t); div.appendChild(lv); div.appendChild(msg);
      frag.appendChild(div);
    });
    logsEl.appendChild(frag);
    while (logsEl.childNodes.length > 300) logsEl.removeChild(logsEl.firstChild);
    if (document.getElementById("autoscroll").checked) logsEl.scrollTop = logsEl.scrollHeight;
  }

  // ------------------------------------------------------------ 主循环
