      if (state.logs && state.logs.length) {
        lastSeq = state.logs[state.logs.length - 1].seq;
        appendLogs(state.logs);
      }
      renderMetrics(state);
      renderCards(state);
      if (!layoutCache || needsRelayout(state)) layoutCache = buildLayout(state);
      draw(layoutCache, state);
    }).catch(function () { /* 轮询失败静默重试 */ });
  }

