  document.getElementById("btn-demo").addEventListener("click", function () { post("/api/demo"); });
  document.getElementById("btn-burst").addEventListener("click", function () { post("/api/burst", { count: 120 }); });
  document.getElementById("btn-fault").addEventListener("click", function () {
    post("/api/inject", { node: "payment-2", latency_ms: 700, loss: 0.4 });
  });
  document.getElementById("btn-clear").addEventListener("click", function () {
    post("/api/clear", { node: "payment-2" });
  });
  document.getElementById("btn-reset").addEventListener("click", function () {
    post("/api/reset").then(function () { logsEl.innerHTML = ""; lastSeq = 0; });
  });
  var slider = document.getElementById("rate-slider");
  slider.addEventListener("change", function () {
    document.getElementById("rate-value").textContent = slider.value + " req/s";
    post("/api/rate", { rps: Number(slider.value) });
  });

  tick();
})();
