"""负载均衡、限流与网格端到端行为测试。"""

import threading
import time
import unittest
from concurrent.futures import as_completed

from meshcore import build_default_mesh
from meshcore.balancer import BackendNode, SmoothWeightedBalancer
from meshcore.mesh import RateLimiter


class SmoothBalancerTest(unittest.TestCase):
    def test_distribution_follows_weights_smoothly(self):
        bal = SmoothWeightedBalancer("svc")
        for i, wlat in enumerate((30.0, 90.0, 200.0)):
            bal.add(BackendNode(f"n{i}", "svc", "x", base_latency_ms=wlat))
        counts = {f"n{i}": 0 for i in range(3)}
        states = {f"n{i}": "CLOSED" for i in range(3)}
        for _ in range(600):
            picked = bal.pick(states)
            counts[picked.node_id] += 1
        # 快节点应明显多于慢节点
        self.assertGreater(counts["n0"], counts["n1"])
        self.assertGreater(counts["n1"], counts["n2"])
        self.assertEqual(sum(counts.values()), 600)

    def test_open_node_never_picked(self):
        bal = SmoothWeightedBalancer("svc")
        for i in range(3):
            bal.add(BackendNode(f"n{i}", "svc", "x", base_latency_ms=40.0))
        states = {f"n{i}": "CLOSED" for i in range(3)}
        states["n1"] = "OPEN"
        for _ in range(100):
            self.assertNotEqual(bal.pick(states).node_id, "n1")

    def test_half_open_gets_tiny_share(self):
        bal = SmoothWeightedBalancer("svc")
        for i in range(2):
            bal.add(BackendNode(f"n{i}", "svc", "x", base_latency_ms=40.0))
        states = {"n0": "CLOSED", "n1": "HALF_OPEN"}
        counts = {"n0": 0, "n1": 0}
        for _ in range(500):
            picked = bal.pick(states)
            if picked:
                counts[picked.node_id] += 1
        # 半开节点权重约为正常 2%，占比应远低于健康节点
        self.assertLess(counts["n1"] / 500.0, 0.1)
        self.assertGreaterEqual(counts["n1"], 1)


