class MeshE2ETest(unittest.TestCase):
    def test_healthy_traffic_succeeds(self):
        mesh = build_default_mesh(breaker_cooldown=2.0)
        futures = [mesh.submit("order") for _ in range(20)]
        results = [f.result(timeout=3)["ok"] for f in futures if f]
        self.assertTrue(all(results))
        self.assertGreaterEqual(mesh.total_success, 18)
        mesh.shutdown()

    def test_fault_opens_breaker_and_heals_after_clear(self):
        mesh = build_default_mesh(breaker_cooldown=2.0)
        mesh.inject_fault("payment-2", latency_ms=900.0, loss=0.9)
        deadline = time.monotonic() + 6.0
        tripped = False
        while time.monotonic() < deadline:
            f = mesh.submit("payment")
            if f:
                f.result(timeout=3)
            snap = mesh.snapshot()
            if snap["nodes"]["payment-2"]["breaker_state"] == "OPEN":
                tripped = True
                break
            time.sleep(0.05)
        self.assertTrue(tripped, "持续超时/错误应触发熔断开启")

        # OPEN 期间 payment-1 仍可服务；存在快速失败/重定向计数
        f = mesh.submit("payment")
        self.assertIsNotNone(f)
        mesh.drain(timeout=5)

        # 等待进入半开：此时仍然故障，应再次打开并重置冷却
        time.sleep(2.4)
        self.assertEqual(mesh.breakers["payment-2"].state.value, "HALF_OPEN")
        deadline = time.monotonic() + 4.0
        reopened = False
        while time.monotonic() < deadline:
            f = mesh.submit("payment")
            if f:
                f.result(timeout=3)
            if mesh.snapshot()["nodes"]["payment-2"]["breaker_state"] == "OPEN":
                reopened = True
                break
            time.sleep(0.05)
        self.assertTrue(reopened, "半开试探失败应重新熔断并重置冷却")

        # 故障恢复 -> 半开 3 次成功 -> CLOSED
        mesh.clear_fault("payment-2")
        time.sleep(2.4)
        deadline = time.monotonic() + 8.0
        healed = False
        while time.monotonic() < deadline:
            f = mesh.submit("payment")
            if f:
                f.result(timeout=3)
            if mesh.snapshot()["nodes"]["payment-2"]["breaker_state"] == "CLOSED" and mesh.breakers["payment-2"].trip_count >= 2:
                healed = True
                break
            time.sleep(0.1)
        self.assertTrue(healed, "故障恢复后半开试探连续成功应自愈")
        mesh.shutdown()

    def test_burst_rate_limit(self):
        mesh = build_default_mesh(limiter_rate=5.0, limiter_burst=4, max_workers=128)
        none_count = 0
        for _ in range(120):
            if mesh.submit("order") is None:
                none_count += 1
        self.assertGreater(none_count, 0)
        mesh.drain(timeout=8)
        mesh.shutdown()

    def test_concurrent_safety_no_deadlock(self):
        mesh = build_default_mesh(breaker_cooldown=2.0)
        errors = []

        def worker(src):
            try:
                for i in range(60):
                    svc = ("order", "payment", "inventory")[src % 3]
                    if i == 20 and src == 0:
                        mesh.inject_fault("order-1", latency_ms=900.0)
                    if i == 40 and src == 0:
                        mesh.clear_fault("order-1")
                    f = mesh.submit(svc)
                    if f:
                        f.result(timeout=5)
                    mesh.snapshot()
            except Exception as exc:  # pragma: no cover - 仅用于失败报告
                errors.append(exc)

        threads = [threading.Thread(target=worker, args=(i,)) for i in range(8)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=30)
            self.assertFalse(t.is_alive(), "出现死锁：工作线程未结束")
        self.assertEqual(errors, [])
        snap = mesh.snapshot()
        self.assertGreater(snap["counters"]["submitted"], 0)
        mesh.shutdown()


